// Тикет #6a86f7e8 F-95 (6a86f7e837c38d2b29bd68b9) — עבר QA 13.10.2026 (iPhone, TestFlight 1.0.0 (19)), проведён пользователем после проверки AC1–4.
//  AC1 — на экране входа нет кнопки внешнего провайдера (Google/Apple/Facebook) — ЭТОТ тест;
//  AC4 — шаринг через системное окно: specs/share/sh-01 (главная, תהילים), specs/achievements/ac-02 (AC-02b, достижение);
//  AC3 — сбой шаринга («השיתוף לא הצליח במכשיר הזה.», карта без изменений) проверен ТОЛЬКО в web (подмена navigator.share):
//        .qa/e2e/tests/impact-map/im-04-share-failure-message.spec.ts. В приложении вызвать сбой системного шаринга нельзя → @manual-check
//        (ручной шаг: если на устройстве шаринг недоступен/падает — должно быть «השיתוף לא הצליח במכשיר הזה.», «N אנשים» не меняется).
// Также факты #f7168d91 (13.10, тикет удалён с доски, поведение проверено): экран входа — «כניסה דרך מספר נייד»,
// «לקבלת קוד הזן את מספר הנייד שלך», без «ההצטרפות מתחילה בדיוק כאן».
// ⚠ Нужен ВЫХОД из аккаунта: before — «התנתקות», after — вход снова.
import { driver, expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, logout } from '../../helpers/app.ts';

async function restoreLogin() {
  for (let i = 0; i < 4; i++) {
    if (await isLoggedIn()) return;
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) break;
    if (await byText('כניסה דרך מספר נייד').isDisplayed().catch(() => false)) break;
    await driver.back();
  }
  await ensureAppReady();
}

describe('Вход', () => {
  before(async () => { await logout(); });
  after(async () => { await restoreLogin(); });

  it('AL-04 Экран входа: только «כניסה דרך מספר נייד», без внешних провайдеров и без «ההצטרפות מתחילה בדיוק כאן» #6a86f7e8 @prod-safe', async () => {
    await (await byText('בואו נתחיל')).click();
    await expect(byText('כניסה דרך מספר נייד')).toBeDisplayed({ wait: 20000 });
    await expect(byTextContains('לקבלת קוד הזן את מספר הנייד שלך')).toBeDisplayed();
    await expect(byTextContains('ההצטרפות מתחילה בדיוק כאן')).not.toBeDisplayed();
    // Нет кнопок внешних провайдеров (AC1).
    await expect(byTextMatches('(?i).*(google|apple|facebook|גוגל|אפל|פייסבוק).*')).not.toBeDisplayed();
    await expect(byTextMatches('.*(התחברות עם|המשך עם|Sign in with|Continue with).*')).not.toBeDisplayed();
  });
});
